import{c,$ as e,Q as y,j as u,g as d,n as p,o,m as n}from"./chunks/framework.CWBTDBPu.js";const x=JSON.parse('{"title":"YuPay 权限节点","description":"","frontmatter":{"title":"YuPay 权限节点"},"headers":[],"relativePath":"plugins/items/yupay/permissions.md","filePath":"plugins/items/yupay/permissions.md"}'),i={name:"plugins/items/yupay/permissions.md"},s={class:"quick-actions"};function h(l,t,m,b,f,_){const a=e("CopyMarkdownButton"),r=e("CopyLLMButton");return y(),u("div",null,[t[0]||(t[0]=d("h1",{id:"yupay-权限节点",tabindex:"-1"},[p("YuPay 权限节点 "),d("a",{class:"header-anchor",href:"#yupay-权限节点","aria-label":'Permalink to "YuPay 权限节点"'},"​")],-1)),d("div",s,[o(a,{page:""}),o(r,{page:""})]),t[1]||(t[1]=n('<p>YuPay 的权限建议按岗位分配：玩家只给基础权限，客服给订单查询和退款申请审核，财务才给直接退款，核心管理员再拥有配置与健康检查权限。</p><h2 id="推荐权限组" tabindex="-1">推荐权限组 <a class="header-anchor" href="#推荐权限组" aria-label="Permalink to &quot;推荐权限组&quot;">​</a></h2><table tabindex="0"><thead><tr><th>角色</th><th>建议权限</th></tr></thead><tbody><tr><td>普通玩家</td><td><code>yupay.user</code></td></tr><tr><td>客服/运营</td><td><code>yupay.order</code>、<code>yupay.refund.pending</code>、<code>yupay.refund.list</code>、<code>yupay.code.info</code>、<code>yupay.code.logs</code></td></tr><tr><td>卡密管理员</td><td><code>yupay.code.admin</code></td></tr><tr><td>财务管理员</td><td><code>yupay.refund</code>，谨慎包含 <code>yupay.refund.direct</code></td></tr><tr><td>核心管理员</td><td><code>yupay.admin</code>、<code>yupay.health</code>、<code>yupay.audit</code>、<code>yupay.crossserver</code></td></tr></tbody></table><h2 id="玩家权限" tabindex="-1">玩家权限 <a class="header-anchor" href="#玩家权限" aria-label="Permalink to &quot;玩家权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>用途</th></tr></thead><tbody><tr><td><code>yupay.user</code></td><td>true</td><td>玩家基础权限合集，包含赞助、排行、总额、历史、订单、自助取消、自助重试、卡密核销和退款申请。</td></tr><tr><td><code>yupay.command.pay</code></td><td>true</td><td>发起赞助。</td></tr><tr><td><code>yupay.command.top</code></td><td>true</td><td>查看赞助排行榜。</td></tr><tr><td><code>yupay.command.total</code></td><td>true</td><td>查看赞助总额。</td></tr><tr><td><code>yupay.command.history</code></td><td>true</td><td>查看赞助历史。</td></tr><tr><td><code>yupay.command.orders</code></td><td>true</td><td>查看订单列表和自己的订单详情。</td></tr><tr><td><code>yupay.command.cancel</code></td><td>true</td><td>取消自己的待支付订单。</td></tr><tr><td><code>yupay.command.retry</code></td><td>true</td><td>自助重试补发奖励。</td></tr><tr><td><code>yupay.command.code</code></td><td>true</td><td>进入卡密命令。</td></tr><tr><td><code>yupay.code.redeem</code></td><td>true</td><td>核销卡密。</td></tr><tr><td><code>yupay.command.refund</code></td><td>true</td><td>进入退款命令。</td></tr><tr><td><code>yupay.refund.request</code></td><td>true</td><td>创建退款申请。</td></tr></tbody></table><h2 id="管理权限" tabindex="-1">管理权限 <a class="header-anchor" href="#管理权限" aria-label="Permalink to &quot;管理权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>用途</th></tr></thead><tbody><tr><td><code>yupay.reload</code></td><td>op</td><td>重载配置。</td></tr><tr><td><code>yupay.ban</code></td><td>op</td><td>禁止或解除玩家赞助。</td></tr><tr><td><code>yupay.convert</code></td><td>op</td><td>货币转换。</td></tr><tr><td><code>yupay.audit</code></td><td>op</td><td>审计信息和安全日志。</td></tr><tr><td><code>yupay.order</code></td><td>op</td><td>订单运维中心。</td></tr><tr><td><code>yupay.health</code></td><td>op</td><td>健康检查。</td></tr><tr><td><code>yupay.crossserver</code></td><td>op</td><td>跨服发奖状态。</td></tr><tr><td><code>yupay.admin</code></td><td>op</td><td>管理员权限合集，包含主要管理命令、卡密管理和退款管理。</td></tr></tbody></table><h2 id="卡密权限" tabindex="-1">卡密权限 <a class="header-anchor" href="#卡密权限" aria-label="Permalink to &quot;卡密权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>用途</th></tr></thead><tbody><tr><td><code>yupay.code.admin</code></td><td>op</td><td>卡密管理权限合集。</td></tr><tr><td><code>yupay.code.*</code></td><td>op</td><td>包含卡密核销与全部卡密管理能力。</td></tr><tr><td><code>yupay.code.create</code></td><td>op</td><td>创建卡密。</td></tr><tr><td><code>yupay.code.remove</code></td><td>op</td><td>删除卡密。</td></tr><tr><td><code>yupay.code.disable</code></td><td>op</td><td>停用卡密。</td></tr><tr><td><code>yupay.code.enable</code></td><td>op</td><td>启用卡密。</td></tr><tr><td><code>yupay.code.modify</code></td><td>op</td><td>修改卡密字段。</td></tr><tr><td><code>yupay.code.info</code></td><td>op</td><td>查看卡密详情。</td></tr><tr><td><code>yupay.code.list</code></td><td>op</td><td>查看卡密列表。</td></tr><tr><td><code>yupay.code.logs</code></td><td>op</td><td>查看核销日志。</td></tr></tbody></table><h2 id="退款权限" tabindex="-1">退款权限 <a class="header-anchor" href="#退款权限" aria-label="Permalink to &quot;退款权限&quot;">​</a></h2><table tabindex="0"><thead><tr><th>权限</th><th>默认</th><th>用途</th></tr></thead><tbody><tr><td><code>yupay.refund</code></td><td>op</td><td>退款管理权限合集。</td></tr><tr><td><code>yupay.refund.approve</code></td><td>op</td><td>通过退款申请。</td></tr><tr><td><code>yupay.refund.reject</code></td><td>op</td><td>拒绝退款申请。</td></tr><tr><td><code>yupay.refund.list</code></td><td>op</td><td>查看退款列表、详情和平台查询。</td></tr><tr><td><code>yupay.refund.pending</code></td><td>op</td><td>查看待审核申请。</td></tr><tr><td><code>yupay.refund.direct</code></td><td>op</td><td>管理员直接退款、确认或重试退款。</td></tr></tbody></table><h2 id="分配建议" tabindex="-1">分配建议 <a class="header-anchor" href="#分配建议" aria-label="Permalink to &quot;分配建议&quot;">​</a></h2><ul><li>不建议把 <code>yupay.admin</code>、<code>yupay.refund.direct</code>、<code>yupay.order</code> 给普通权限组。</li><li>有真实资金流的服务器，退款审核与直接退款最好分配给不同人员。</li><li>卡密运营只需要 <code>yupay.code.admin</code>，无需获得支付配置、跨服队列或健康检查权限。</li><li>如果使用 LuckPerms，可以先给默认组 <code>yupay.user</code>，再给管理组追加具体节点。</li></ul>',13))])}const q=c(i,[["render",h]]);export{x as __pageData,q as default};
